import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { 
  ChevronLeft, Calendar, User, MapPin, Clock, 
  MoreVertical, Search, Layers, ChevronDown, Plus, Minus,
  Monitor, Mic, Video, Tablet, Edit3, Camera 
} from 'lucide-react';
import './MeetingRoom.css';

const MeetingRoom = () => {
  const navigate = useNavigate();
  
  // --- 状态定义 (解决变量未定义报错) ---
  const [view, setView] = useState('list'); // 'list', 'results', 'filter', 'booking'
  const [attendees, setAttendees] = useState(0);
  const [selectedRoom, setSelectedRoom] = useState(null);

  // 日历逻辑状态
  const [isCalendarOpen, setIsCalendarOpen] = useState(false);
  const [selectedDate, setSelectedDate] = useState(new Date(2026, 0, 22)); // 默认选中 2026-01-22
  const [viewDate, setViewDate] = useState(new Date(2026, 0, 1)); // 日历面板显示的月份

  // 下拉选择状态
  const [selectedStartTime, setSelectedStartTime] = useState('');
  const [selectedDuration, setSelectedDuration] = useState('');
  const [selectedFloor, setSelectedFloor] = useState('');

  // --- 1. 完整的设施列表 (还原 7 项) ---
  const allFeatures = [
    "Projector", "Interactive TV", "Non-Interactive TV", 
    "180° Camera", "Conference Camera", "Tabletop Teams Panel", "Wireless Mic"
  ];

  // --- 2. 时间选择器逻辑 (10:00 AM - 8:00 PM) ---
  const timeSlots = [];
  for (let hour = 10; hour <= 20; hour++) {
    const period = hour < 12 ? 'AM' : 'PM';
    const displayHour = hour > 12 ? hour - 12 : (hour === 0 ? 12 : hour);
    timeSlots.push(`${displayHour}:00 ${period}`);
    if (hour !== 20) timeSlots.push(`${displayHour}:30 ${period}`);
  }

  // --- 3. 动态时长逻辑 (Start + Duration <= 8:00 PM) ---
  const getAvailableDurations = () => {
    if (!selectedStartTime) return [];
    
    // 解析选中时间为 24 小时制数字 (例如 "5:30 PM" -> 17.5)
    const [time, period] = selectedStartTime.split(' ');
    let [h, m] = time.split(':').map(Number);
    if (period === 'PM' && h !== 12) h += 12;
    if (period === 'AM' && h === 12) h = 0;
    const startNum = h + (m / 60);
    
    const maxAllowed = 20 - startNum; // 距离 20:00 (8:00 PM) 的剩余小时
    const list = [];
    
    // 生成选项：步长 0.5h，最高 5h，且不能超过 maxAllowed
    for (let i = 0.5; i <= Math.min(5, maxAllowed); i += 0.5) {
      if (i === 0.5) {
        list.push("30 min");
      } else {
        const fullHours = Math.floor(i);
        const mins = (i % 1) * 60;
        list.push(`${fullHours} hour${fullHours > 1 ? 's' : ''}${mins > 0 ? ' 30 min' : ''}`);
      }
    }
    return list;
  };

  // --- 4. 自定义日历逻辑 (支持年月切换) ---
  const changeMonth = (offset) => {
    setViewDate(new Date(viewDate.getFullYear(), viewDate.getMonth() + offset, 1));
  };

  const renderCalendarDays = () => {
    const year = viewDate.getFullYear();
    const month = viewDate.getMonth();
    const firstDay = new Date(year, month, 1).getDay(); // 0 是周日
    const daysInMonth = new Date(year, month + 1, 0).getDate();
    const startOffset = firstDay === 0 ? 6 : firstDay - 1; // 转换为周一开始

    const days = [];
    // 填充空白
    for (let i = 0; i < startOffset; i++) days.push(<span key={`empty-${i}`} className="day-empty"></span>);
    // 填充日期数字
    for (let d = 1; d <= daysInMonth; d++) {
      const isSelected = selectedDate.getDate() === d && selectedDate.getMonth() === month && selectedDate.getFullYear() === year;
      const isPast = new Date(year, month, d) < new Date(2026, 0, 22); // 示例：22号之前不可选
      days.push(
        <div 
          key={d} 
          className={`calendar-day ${isSelected ? 'selected' : ''} ${isPast ? 'past' : ''}`}
          onClick={() => !isPast && setSelectedDate(new Date(year, month, d))}
        >
          {d}
        </div>
      );
    }
    return days;
  };

  const handleBack = () => {
    if (view === 'booking') setView('results');
    else if (view === 'filter') setView('results');
    else if (view === 'results') setView('list');
    else navigate('/');
  };

  const todayStr = new Date().toISOString().split('T')[0];
  const fiveYearsLater = new Date();
  fiveYearsLater.setFullYear(fiveYearsLater.getFullYear() + 5);
  const maxDateStr = fiveYearsLater.toISOString().split('T')[0];

  return (
    <div className="meeting-room-container">
      <nav className="top-nav-bar">
        <div className="back-arrow-wrapper" onClick={handleBack}>
          <ChevronLeft size={24} color="#ffffff" strokeWidth={2.5} />
        </div>
        <span className="nav-title">
          {view === 'booking' ? "Meeting Room Details" : (view === 'filter' ? "Searching" : "Meeting Room")}
        </span>
      </nav>

      <div className="scrollable-area">
        {view === 'list' && (
          <div className="content-padding">
            <div className="tabs-header">
              <button className="tab active">List All</button>
              <button className="tab">Today</button>
              <button className="tab">Week</button>
            </div>
            <div className="summary-banner">
              <div className="summary-icon"><Calendar size={22} color="#1976d2" /></div>
              <div className="summary-info">
                <h2 style={{ fontSize: "13pt", fontWeight: "bold", margin: 0 }}>1 Meeting Upcoming</h2>
                <p style={{ fontSize: "10pt", fontWeight: "bold", margin: "2px 0 0", color: "#000000" }}>22 Jan, Thursday</p>
              </div>
            </div>
            <div className="meeting-list">
              <div className="details-card">
                <div className="card-top">
                  <h3 style={{margin: 0, fontSize: '15px'}}>UAT Briefing</h3>
                  <button className="more-options"><MoreVertical size={20} color="#999" /></button>
                </div>
                <div className="info-rows">
                  <div className="row"><span className="icon"><User size={18} /></span><span className="text">ALAN TAN WAI LOON</span></div>
                  <div className="row"><span className="icon"><MapPin size={18} /></span><span className="text">Idea Lab 6</span></div>
                  <div className="row"><span className="icon"><Calendar size={18} /></span><span className="text">2026-01-22</span></div>
                  <div className="row"><span className="icon"><Clock size={18} /></span><span className="text">12:00 PM - 12:30 PM</span></div>
                </div>
                <div className="card-bottom">
                  <div className="attendee-count">
                    <div className="icon-circle"><User size={14} strokeWidth={2.5} /></div>
                    <span className="attendee-number">1</span>
                  </div>
                </div>
              </div>
            </div>
          </div>
        )}

        {view === 'results' && (
          <div className="search-view-container">
            <button className="search-input-trigger" onClick={() => setView('filter')}>
              <span className="placeholder-text">Search room name...</span>
              <Search size={20} color="#999" />
            </button>
            <div className="search-results-list">
              {[...Array(10)].map((_, index) => (
                <div key={index} className="room-sub-box" onClick={() => { setSelectedRoom(index + 1); setView('booking'); }}>
                  <div className="room-box-left"></div>
                  <div className="room-box-right">
                    <h4 className="room-title">Idea Lab {index + 1}</h4>
                    <div className="room-details">
                      <div className="detail-item"><User size={14} color="#666" /> <span>8 seats</span></div>
                      <div className="detail-item"><Layers size={14} color="#666" /> <span>Level 19</span></div>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}

        {view === 'filter' && (
          <div className="filter-form-wrapper">
            <p className="form-subtitle">Find A Meeting Room</p>
            <div className="field-group">
              <label>Date</label>
              <div className="form-field-box" onClick={() => setIsCalendarOpen(true)}>
                <span>{selectedDate.toISOString().split('T')[0]}</span>
                <Calendar size={18} color="#666" />
              </div>
            </div>

            <div className="field-group">
              <label>I need a meeting room from</label>
              <div className="form-field-box select-type">
                <select value={selectedStartTime} onChange={(e) => { setSelectedStartTime(e.target.value); setSelectedDuration(''); }}>
                  <option value="">Please Select Time</option>
                  {timeSlots.map(t => <option key={t} value={t}>{t}</option>)}
                </select>
                <ChevronDown size={18} color="#666" className="select-arrow" />
              </div>
            </div>

            <div className="field-group">
              <label>I need a meeting room for</label>
              <div className="form-field-box select-type">
                <select value={selectedDuration} onChange={(e) => setSelectedDuration(e.target.value)} disabled={!selectedStartTime}>
                  <option value="">{selectedStartTime ? "Please Select Duration" : "Select Start Time First"}</option>
                  {getAvailableDurations().map(d => <option key={d} value={d}>{d}</option>)}
                </select>
                <ChevronDown size={18} color="#666" className="select-arrow" />
              </div>
            </div>

            <div className="field-group">
              <label>Floor</label>
              <div className="form-field-box select-type">
                <select value={selectedFloor} onChange={(e) => setSelectedFloor(e.target.value)}>
                  <option value="">Please select a Floor</option>
                  <option value="19">Level 19</option>
                </select>
                <ChevronDown size={18} color="#666" className="select-arrow" />
              </div>
            </div>

            <div className="feature-section">
              <label className="section-label">Room Features</label>
              {allFeatures.map(item => (
                <div className="feature-row-item" key={item}>
                  <span>{item}</span>
                  <input type="checkbox" className="custom-checkbox" />
                </div>
              ))}
            </div>

            <div className="attendee-stepper">
              <label>Number of Attendees</label>
              <div className="stepper-controls">
                <button className="step-btn" onClick={() => setAttendees(Math.max(0, attendees - 1))}><Minus size={18} /></button>
                <span className="step-value">{attendees}</span>
                <button className="step-btn" onClick={() => setAttendees(Math.min(8, attendees + 1))}><Plus size={18} /></button>
              </div>
            </div>

            <div className="form-footer">
              <button className="capsule-search-btn" onClick={() => setView('results')}>Search Room</button>
            </div>
          </div>
        )}

        {view === 'booking' && (
          <div className="booking-details-container">
            <div className="room-hero-image">
              <div className="room-label-tag">Idea Lab {selectedRoom}</div>
            </div>

            <div className="room-details-content">
              <h2 className="room-main-title">Signature Teams Room</h2>
              
              <div className="features-info-card">
                <h3 className="features-title">Room Features</h3>
                <div className="features-grid-layout">
                  <div className="f-item"><User size={16} color="#00a8ff" /> <span>8 seats</span></div>
                  <div className="f-item"><Monitor size={16} color="#00a8ff" /> <span>Projector</span></div>
                  <div className="f-item"><Video size={16} color="#00a8ff" /> <span>Interactive TV</span></div>
                  <div className="f-item"><Video size={16} color="#00a8ff" /> <span>Non-Interactive TV</span></div>
                  <div className="f-item"><Camera size={16} color="#00a8ff" /> <span>180° Camera</span></div>
                  <div className="f-item"><Camera size={16} color="#00a8ff" /> <span>Conference Camera</span></div>
                  <div className="f-item"><Tablet size={16} color="#00a8ff" /> <span>Tabletop Teams Panel</span></div>
                  <div className="f-item"><Mic size={16} color="#00a8ff" /> <span>Wireless Mic</span></div>
                </div>
              </div>

              <div className="schedule-info-card">
                <h3 className="schedule-header">Please select a time slot</h3>
                <div className="field-group">
                  <div className="form-field-box" onClick={() => setIsCalendarOpen(true)}>
                    <span>{selectedDate.toISOString().split('T')[0]}</span>
                    <Calendar size={18} color="#666" />
                  </div>
                </div>
                <div className="field-group">
                  <div className="form-field-box select-type">
                    <select value={selectedStartTime} onChange={(e) => { setSelectedStartTime(e.target.value); setSelectedDuration(''); }}>
                      <option value="">Start Time</option>
                      {timeSlots.map(t => <option key={t} value={t}>{t}</option>)}
                    </select>
                    <ChevronDown size={18} color="#666" className="select-arrow" />
                  </div>
                </div>
                <div className="field-group">
                  <div className="form-field-box select-type">
                    <select value={selectedDuration} onChange={(e) => setSelectedDuration(e.target.value)} disabled={!selectedStartTime}>
                      <option value="">Length</option>
                      {getAvailableDurations().map(d => <option key={d} value={d}>{d}</option>)}
                    </select>
                    <ChevronDown size={18} color="#666" className="select-arrow" />
                  </div>
                </div>
                <p className="no-booking-msg">No Booking for the day yet!</p>
              </div>
            </div>
          </div>
        )}
      </div>

      {isCalendarOpen && (
        <div className="calendar-overlay">
          <div className="calendar-modal">
            <div className="calendar-modal-header">
              <span>Calendar</span>
              <button className="close-btn" onClick={() => setIsCalendarOpen(false)}>×</button>
            </div>
            <div className="calendar-nav">
              <button className="nav-arrow" onClick={() => changeMonth(-1)}>{'<'}</button>
              <span className="month-year">{viewDate.toLocaleString('default', { month: 'long', year: 'numeric' })}</span>
              <button className="nav-arrow" onClick={() => changeMonth(1)}>{'>'}</button>
            </div>
            <div className="weekday-row">
              {['Mo', 'Tu', 'We', 'Th', 'Fr', 'Sa', 'Su'].map(d => <span key={d}>{d}</span>)}
            </div>
            <div className="days-grid">
              {renderCalendarDays()}
            </div>
            <div className="calendar-footer">
              <button className="calendar-confirm-btn" onClick={() => setIsCalendarOpen(false)}>CONFIRM</button>
            </div>
          </div>
        </div>
      )}

      <div className="search-footer">
        {view === 'list' ? (
          <button className="search-room-btn" onClick={() => setView('results')}>
            <Search size={18} style={{marginRight: '8px'}} /> Search Room
          </button>
        ) : view === 'booking' ? (
          <button className="book-room-btn">Book Now</button>
        ) : null}
      </div>
    </div>
  );
};

export default MeetingRoom;
